-- German A1 Unit 10 — personal forms, common signs and short phone messages.
-- Base content never overwrites generated audio state.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
SET @iris := (SELECT id FROM characters WHERE character_key='char-de-iris' LIMIT 1);
SET @paul := (SELECT id FROM characters WHERE character_key='char-de-paul' LIMIT 1);

ON DUPLICATE KEY UPDATE title=VALUES(title),title_fa=VALUES(title_fa),organization_or_author=VALUES(organization_or_author),language_code=VALUES(language_code),source_type=VALUES(source_type),url=VALUES(url),locator=VALUES(locator),locator_fa=VALUES(locator_fa),published_or_updated_at=VALUES(published_or_updated_at),modernity_status=VALUES(modernity_status),currency_evidence=VALUES(currency_evidence),license_name=VALUES(license_name),license_url=VALUES(license_url),attribution_text=VALUES(attribution_text),reuse_status=VALUES(reuse_status),retrieved_at=VALUES(retrieved_at),notes=VALUES(notes);
SET @s_form := (SELECT id FROM sources WHERE source_key='src-wikibooks-de-lesson-007-form-spelling');
SET @s_sign := (SELECT id FROM sources WHERE source_key='src-wikivoyage-german-phrasebook-signs');
SET @s_msg := (SELECT id FROM sources WHERE source_key='src-wikibooks-de-lesson-024-short-messages');

ON DUPLICATE KEY UPDATE source_id=VALUES(source_id),locator=VALUES(locator),locator_fa=VALUES(locator_fa),source_text=VALUES(source_text),source_text_hash=VALUES(source_text_hash),notes=VALUES(notes);

ON DUPLICATE KEY UPDATE sequence_index=VALUES(sequence_index),title_fa=VALUES(title_fa),grouping_rationale=VALUES(grouping_rationale),status=IF(status='final',status,VALUES(status)),metadata=VALUES(metadata),notes=VALUES(notes);
SET @unit := (SELECT id FROM units WHERE unit_key='de-a1-unit-forms-signs-messages');

SET @t_listen_dialogue := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-listening-dialogue');
SET @t_listen_msg := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-listening-message-announcement');
SET @t_read := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-reading-short-texts');
SET @t_write := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-writing-form-message');
SET @t_spoken := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-spoken-questions-requests');
SET @t_short := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-sit-short-messages');
SET @t_core := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-core-vocabulary');
SET @t_word := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-basic-word-order');
SET @t_time := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-numbers-dates-time');
SET @t_pron := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-pron-intelligibility');

ON DUPLICATE KEY UPDATE language_id=VALUES(language_id),lexeme_type=VALUES(lexeme_type),surface=VALUES(surface),normalized_surface=VALUES(normalized_surface),lemma=VALUES(lemma),part_of_speech=VALUES(part_of_speech),part_of_speech_fa=VALUES(part_of_speech_fa),cefr_level=VALUES(cefr_level),translation_fa=VALUES(translation_fa),usage_note_fa=VALUES(usage_note_fa),flashcard_eligible=VALUES(flashcard_eligible);

SET @x_vorname=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-vorname'); SET @x_familienname=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-familienname'); SET @x_adresse=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-adresse'); SET @x_stadt=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-stadt'); SET @x_buch=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-buchstabieren'); SET @x_offen=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-offen'); SET @x_geschlossen=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-geschlossen'); SET @x_eingang=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-eingang'); SET @x_ausgang=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-ausgang'); SET @x_wohnen=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-wohnen'); SET @x_oesterreich=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-oesterreich');
SET @x_anrufen=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-anrufen'); SET @x_montag=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-montag'); SET @x_nachmittag=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-nachmittag'); SET @x_uebermorgen=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-uebermorgen'); SET @x_morgen_adv=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-morgen-adverb'); SET @x_noch=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-noch-einmal'); SET @x_moegen=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-moegen'); SET @x_ja=(SELECT id FROM lexemes WHERE lexeme_key='lex-de-ja');
SET @f_moechten=(SELECT id FROM lexeme_forms WHERE lexeme_form_key='lexform-de-moegen-moechten'); SET @f_moechte=(SELECT id FROM lexeme_forms WHERE lexeme_form_key='lexform-de-moegen-moechte');

ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),unit_id=VALUES(unit_id),sequence_index=VALUES(sequence_index),position_in_unit=VALUES(position_in_unit),title_fa=VALUES(title_fa),source_title=VALUES(source_title),source_title_fa=VALUES(source_title_fa),status=VALUES(status),activity_selection_rationale=VALUES(activity_selection_rationale),sequence_rationale=VALUES(sequence_rationale),template_signature=VALUES(template_signature),notes=VALUES(notes);
SET @l1=(SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-personal-form-signs'); SET @l2=(SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-short-phone-message');


ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),scenario=VALUES(scenario),opening_initiator=VALUES(opening_initiator),scene_quality_rationale=VALUES(scene_quality_rationale);
SET @d1=(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-personal-form-review'); SET @d2=(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-short-message-coordination');

ON DUPLICATE KEY UPDATE dialogue_id=VALUES(dialogue_id),position_index=VALUES(position_index),speaker_character_id=VALUES(speaker_character_id),speaker_identity_origin=VALUES(speaker_identity_origin),speaker_gender_evidence=VALUES(speaker_gender_evidence),text_target=VALUES(text_target),translation_fa=VALUES(translation_fa),learner_turn=VALUES(learner_turn);

ON DUPLICATE KEY UPDATE lesson_id=VALUES(lesson_id),position_index=VALUES(position_index),activity_type=VALUES(activity_type),instruction_fa=VALUES(instruction_fa),selection_reason=VALUES(selection_reason),dialogue_id=VALUES(dialogue_id),payload=VALUES(payload),transformations=VALUES(transformations),audio_text_target=VALUES(audio_text_target);

SET @a11=(SELECT id FROM activities WHERE activity_key='act-de-a1-form-conversation'); SET @a12=(SELECT id FROM activities WHERE activity_key='act-de-a1-form-fields-matching'); SET @a13=(SELECT id FROM activities WHERE activity_key='act-de-a1-form-first-name-fill'); SET @a14=(SELECT id FROM activities WHERE activity_key='act-de-a1-common-signs-matching'); SET @a15=(SELECT id FROM activities WHERE activity_key='act-de-a1-alphabet-pronunciation');
SET @a21=(SELECT id FROM activities WHERE activity_key='act-de-a1-message-conversation'); SET @a22=(SELECT id FROM activities WHERE activity_key='act-de-a1-message-listen-callback'); SET @a23=(SELECT id FROM activities WHERE activity_key='act-de-a1-message-reading-matching'); SET @a24=(SELECT id FROM activities WHERE activity_key='act-de-a1-message-write-order');


ON DUPLICATE KEY UPDATE owner_type=VALUES(owner_type),owner_key=VALUES(owner_key),surface=VALUES(surface),lexeme_id=VALUES(lexeme_id),lexeme_form_id=VALUES(lexeme_form_id),resolution_status=VALUES(resolution_status),resolution_notes=VALUES(resolution_notes);

SET @si_guten=(SELECT id FROM source_items WHERE item_key='srcitem-de-guten-tag'); SET @si_nameq=(SELECT id FROM source_items WHERE item_key='srcitem-de-wie-heissen-sie'); SET @si_namea=(SELECT id FROM source_items WHERE item_key='srcitem-de-ich-heisse-paul'); SET @si_wohnq=(SELECT id FROM source_items WHERE item_key='srcitem-de-wo-wohnen-sie'); SET @si_wohna=(SELECT id FROM source_items WHERE item_key='srcitem-de-ich-wohne-oesterreich');
SET @si_vor=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-vorname'); SET @si_fam=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-familienname'); SET @si_addr=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-adresse'); SET @si_stadt=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-stadt'); SET @si_first=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-example-first'); SET @si_family=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-example-family'); SET @si_street=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-example-street'); SET @si_city=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-example-city');
SET @si_alpha1=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-alpha-1'); SET @si_alpha2=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-alpha-2'); SET @si_alpha3=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-alpha-3'); SET @si_alpha4=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-alpha-4'); SET @si_alpha5=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-alpha-5'); SET @si_alpha6=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-form-alpha-6');
SET @si_open=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-sign-open'); SET @si_closed=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-sign-closed'); SET @si_enter=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-sign-entrance'); SET @si_exit=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-sign-exit');
SET @si_qcall=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-q-call'); SET @si_acall=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-a-call'); SET @si_qpick=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-q-pickup'); SET @si_apick=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-a-pickup'); SET @si_mon=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-monday'); SET @si_even=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-evening'); SET @si_over=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-day-after'); SET @si_ten=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-ten'); SET @si_after=(SELECT id FROM source_items WHERE item_key='srcitem-de-a1-msg-afternoon');


UPDATE language_levels SET coverage=JSON_SET(coverage,'$.gaps[2]','ده واحد محتوایی به بازبینی رسیده‌اند؛ مرحلهٔ بعد بررسی سراسری پوشش هدف‌ها و رفع شکاف‌های واقعی پیش از تغییر وضعیت سطح است.','$.gaps[3]','پوشش شنیدن، خواندن، نوشتن و گفتار اکنون در واحدهای محتوایی توزیع شده است؛ در بررسی سراسری باید کفایت و توازن آن‌ها دوباره سنجیده شود.'),notes='A1 همچنان در مرحلهٔ ساخت و بررسی است. ده واحد محتوایی در وضعیت بازبینی‌اند. مرحلهٔ بعد، بررسی سراسری هدف‌های ارتباطی، زبانی و موقعیتی و رفع هر شکاف واقعی پیش از انتقال کل سطح به بازبینی است.' WHERE id=@level;
COMMIT;
