INSERT INTO sources(source_key,title,title_fa,organization_or_author,language_code,source_type,url,locator,locator_fa,published_or_updated_at,modernity_status,currency_evidence,license_name,license_url,attribution_text,reuse_status,retrieved_at,notes) VALUES
('src-wikibooks-de-lesson-007-form-spelling','Deutschkurs für Anfänger/Lektion 007','هجی‌کردن و اطلاعات فرم شخصی','Wikibooks contributors','de','course','https://en.wikibooks.org/wiki/Deutschkurs_f%C3%BCr_Anf%C3%A4nger/Lektion_007','Items 294, 297, 298 and 304: alphabet groups, spelling language, personal-form labels and example values.','بخش‌های ۲۹۴، ۲۹۷، ۲۹۸ و ۳۰۴؛ الفبا، هجی‌کردن، برچسب‌های فرم و مثال‌های اطلاعات شخصی.','2025-01-04','contemporary_verified','صفحهٔ زندهٔ ویکی‌بوکس در ۱۸ سپتامبر ۲۰۲۶ دوباره بررسی شد و آخرین ویرایش ثبت‌شدهٔ آن ۴ ژانویهٔ ۲۰۲۵ است. بخش‌های انتخاب‌شده فقط حروف الفبا، هجی‌کردن و برچسب‌های اطلاعات شخصی را پوشش می‌دهند و در بازبینی فعلی طبیعی و قابل‌استفاده‌اند.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — Deutschkurs für Anfänger/Lektion 007','reuse_with_attribution','2026-09-18','استفاده به بخش‌های ۲۹۴، ۲۹۷، ۲۹۸ و ۳۰۴ محدود است. مثال‌های نام، نام خانوادگی، نام خیابان و شهر فقط در فعالیت هدایت‌شدهٔ فرم استفاده می‌شوند.'),
('src-wikivoyage-german-phrasebook-signs','German phrasebook — Common signs','تابلوهای بسیار کوتاه روزمره','Wikivoyage contributors','de','website','https://en.wikivoyage.org/wiki/German_phrasebook','Basics — Common signs: open, closed, entrance and exit.','بخش تابلوهای رایج؛ باز، بسته، ورودی و خروجی.',NULL,'maintained_current','بخش تابلوهای رایج در عبارت‌نامهٔ آلمانی ویکی‌ویاژ در ۱۸ سپتامبر ۲۰۲۶ بررسی شد. چهار تابلوی انتخاب‌شده در نسخهٔ فعلی صفحه حضور دارند و برای خواندن متن‌های بسیار کوتاه روزمره مناسب‌اند.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikivoyage contributors — German phrasebook','reuse_with_attribution','2026-09-18','فقط چهار تابلوی بسیار پرتکرار مربوط به بازبودن، بسته‌بودن، ورودی و خروجی وارد این واحد می‌شوند.'),
('src-wikibooks-de-lesson-024-short-messages','Deutschkurs für Anfänger/Lektion 024','پیام کوتاه تماس و هماهنگی','Wikibooks contributors','de','course','https://en.wikibooks.org/wiki/Deutschkurs_f%C3%BCr_Anf%C3%A4nger/Lektion_024','Items 1007 and 1010: callback messages and short coordination question-answer pairs.','بخش‌های ۱۰۰۷ و ۱۰۱۰؛ پیام‌های تماس و پرسش‌وپاسخ کوتاه برای هماهنگی.','2024-12-04','contemporary_verified','صفحهٔ زندهٔ ویکی‌بوکس در ۱۸ سپتامبر ۲۰۲۶ دوباره بررسی شد و آخرین ویرایش ثبت‌شدهٔ آن ۴ دسامبر ۲۰۲۴ است. پیام‌های تماس و جفت‌های کوتاه هماهنگی انتخاب‌شده در بازبینی فعلی طبیعی و مناسب ارتباط روزمره‌اند.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — Deutschkurs für Anfänger/Lektion 024','reuse_with_attribution','2026-09-18','استفاده به بخش‌های ۱۰۰۷ و ۱۰۱۰ محدود است. پیام‌های کوتاه تماس برای شنیدن، خواندن و بازسازی هدایت‌شده به کار می‌روند؛ بخش‌های دستوری پیشرفته‌تر صفحه وارد این سطح نمی‌شوند.')
