INSERT INTO units(unit_key,language_level_id,sequence_index,title_fa,grouping_rationale,status,metadata,notes) VALUES
('de-a1-unit-forms-signs-messages',@level,10,'فرم، تابلو و پیام کوتاه','واحد پایانی مهارت‌های کوتاه اما واقعی بیرون از گفت‌وگوی آزاد را کنار هم می‌آورد: فرم و هجی‌کردن، تابلوهای محیطی و پیام تماس. دو درس جدا نگه داشته شده‌اند چون خواندن و تکمیل فرم با دریافت و تولید پیام کوتاه نیازهای متفاوتی دارند.','review',JSON_OBJECT('sourceRefs',JSON_ARRAY('src-wikibooks-de-residence-origin','src-wikibooks-de-lesson-007-form-spelling','src-wikivoyage-german-phrasebook-signs','src-wikibooks-de-lesson-024-short-messages'),'learningTargets',JSON_ARRAY('فرم و اطلاعات شخصی','تابلوهای کوتاه','هجی و وضوح حروف','پیام کوتاه شنیداری','بازسازی پیام کوتاه')),'بازبینی پوشش انجام شد. درس نخست فرم، تابلو و تلفظ حروف را پوشش می‌دهد؛ درس دوم گفت‌وگوی هماهنگی، پیام شنیداری، خواندن پیام و بازسازی نوشتاری را اضافه می‌کند. مرحلهٔ بعد بررسی پوشش کل سطح و رفع شکاف‌های واقعی پیش از تغییر وضعیت A1 است.')
