('lex-de-geschlossen',@de,'word','Geschlossen','Geschlossen','geschlossen','adjective','صفت','A1','بسته','روی تابلوی کوتاه برای نشان‌دادن بسته بودن مکان استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-eingang',@de,'word','Eingang','Eingang','Eingang','noun','اسم','A1','ورودی','روی تابلوی کوتاه برای مشخص‌کردن ورودی استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-ausgang',@de,'word','Ausgang','Ausgang','Ausgang','noun','اسم','A1','خروجی','روی تابلوی کوتاه برای مشخص‌کردن خروجی استفاده می‌شود.',TRUE,'blocked_until_level_final'),
