('lex-de-morgen-adverb',@de,'word','morgen','morgen','morgen','adverb','قید','A1','فردا','این مدخل از «Morgen» به معنی صبح جداست و در هماهنگی برنامه به معنی فردا استفاده می‌شود.',TRUE,'blocked_until_level_final')
INSERT INTO lessons(lesson_key,language_level_id,unit_id,sequence_index,position_in_unit,title_fa,source_title,source_title_fa,status,activity_selection_rationale,sequence_rationale,template_signature,audio_status,notes) VALUES
('de-a1-lesson-personal-form-signs',@level,@unit,15,1,'فرم را پر کن، تابلو را بخوان','Vorname / Familienname / Adresse / Stadt — common signs','نام کوچک، نام خانوادگی، نشانی، شهر و تابلوهای رایج','draft','درس با بازیابی اطلاعات شخصی شروع می‌شود؛ سپس برچسب‌های فرم، تکمیل یک فیلد واقعی، خواندن چهار تابلوی کوتاه و در پایان خواندن حروف برای هجی‌کردن تمرین می‌شوند.','ترتیب از تعامل آشنا به خواندن فرم، تولید هدایت‌شده، خواندن متن محیطی و سپس وضوح تلفظ حروف حرکت می‌کند.','conversation_speaking>matching>fill_blank>matching>pronunciation_read','blocked_until_level_final','درس نخست واحد پایانی، فرم و تابلو و هجی را در یک مسیر کاربردی ترکیب می‌کند.'),
('de-a1-lesson-short-phone-message',@level,@unit,16,2,'لطفاً دوشنبه دوباره تماس بگیرید','Rufen Sie bitte am Montag noch einmal an.','لطفاً دوشنبه دوباره تماس بگیرید','draft','گفت‌وگو هماهنگی کوتاه را می‌سازد؛ سپس یک پیام مستقل شنیده می‌شود، چهار پیام زمانی خوانده و تطبیق داده می‌شوند و در پایان یک پیام دیگر بازسازی می‌شود.','درس از تعامل به دریافت شنیداری، سپس خواندن چند نمونه و در پایان تولید هدایت‌شدهٔ پیام کوتاه حرکت می‌کند.','conversation_speaking>listen_choose>matching>word_order','blocked_until_level_final','درس دوم واحد پایانی، پیام کوتاه را در دریافت شنیداری، خواندن و تولید هدایت‌شده پوشش می‌دهد.')
