INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-personal-form-review',@level,'آیریس در یک ثبت‌نام کوتاه اطلاعات پایهٔ پاول را مرور می‌کند: سلام، نام و محل زندگی.','app','شش نوبت عین نمونه‌های منبع‌دار سطح پیشین‌اند و فقط در یک موقعیت ثبت‌نام کوتاه دوباره کنار هم قرار گرفته‌اند؛ هیچ متن آلمانی تازه‌ای برای فرم ساخته نشده است.'),
('dlg-de-a1-short-message-coordination',@level,'آیریس و پاول در یک تماس کوتاه دو کار را هماهنگ می‌کنند: تماس دوباره برای فردا و گرفتن کارت‌ها در فردا.','app','چهار نوبت از دو جفت پرسش‌وپاسخ مجاور بخش ۱۰۱۰ عیناً حفظ شده‌اند و به‌عنوان دو کار کوتاه در یک تماس هماهنگی کنار هم قرار گرفته‌اند. نقش شخصیت‌ها افزوده شده اما متن آلمانی تغییر نکرده است.')
