('turn-de-a1-form-2',@d1,2,@paul,'app_assigned','unspecified','Guten Tag!','سلام / روز بخیر!',TRUE,'blocked_until_level_final'),
('turn-de-a1-form-3',@d1,3,@iris,'app_assigned','unspecified','Wie heißen Sie?','اسمتان چیست؟',FALSE,'blocked_until_level_final'),
